    /** مفاتيح من التطبيق مالهاش رمز في القايمة (تصنيفات المستحقات) ⇒ أقرب رمز مشترك. */
    private val aliases: Map<String, Lucide> = mapOf(
        "tag" to Lucide.TAG,
        "users-round" to Lucide.USERS,
        "landmark" to Lucide.BUILDING_2,
    )

    /** الرمز بمفتاحه — مفتاح مش معروف ⇒ رمز «تصنيف» عام (مش فاضي). */
    fun of(key: String?): Lucide = key?.let { byKey[it] ?: aliases[it] } ?: Lucide.TAG
}

/** رمز التصنيف بمفتاحه (`Category.iconKey`). */
internal fun categoryIcon(key: String?): Lucide = CategoryIcons.of(key)
